import { supabase } from "@/lib/supabase";

/**
 * Service to handle fetching and parsing of Blade Manifest JSONs.
 * These manifests are generated by the Desktop App and contain
 * calibrated Virtual Ruler data (GSD, Radius, Sequence).
 */
const BLADE_SEGMENT = /^(blade|pala)\s*[abc]$/i;

/** Descarga un manifest.json del bucket "images"; null si no existe o no hay permiso. */
async function downloadManifest(path) {
  try {
    const { data, error } = await supabase.storage.from("images").download(path);
    if (error || !data) return null;
    return JSON.parse(await data.text());
  } catch (err) {
    console.error(`[BladeManifestService] Error parsing manifest:`, err);
    return null;
  }
}

export const BladeManifestService = {
  /**
   * Manifest de la pala a la que pertenece una foto, deduciendo la carpeta desde su storage_path
   * (".../<WTG>/Blade A/<sección>/foto.jpg" -> ".../<WTG>/Blade A/manifest.json").
   * Sirve para cualquier raíz: parque (proyectos existentes) o PARQUE/AAAA_id8 (proyectos nuevos).
   */
  async fetchManifestForImage(storagePath) {
    if (!storagePath || /^https?:\/\//i.test(storagePath)) return null;
    const parts = storagePath.split("/");
    const idx = parts.findIndex((p) => BLADE_SEGMENT.test(p));
    if (idx < 1) return null;
    return downloadManifest(`${parts.slice(0, idx + 1).join("/")}/manifest.json`);
  },

  /**
   * Fetch the manifest.json for a specific blade.
   * @param {string} projectId - Project ID or Name (for storage path)
   * @param {string} turbineName - WTG Name
   * @param {string} bladeLetter - 'A', 'B', or 'C'
   * @returns {Promise<Object|null>} The parsed manifest or null if not found.
   */
  async fetchManifest(projectId, turbineName, bladeLetter) {
    if (!projectId || !turbineName || !bladeLetter) return null;

    // Storage Path Convention: "{WindFarm}/{Turbine}/Blade {Letter}/manifest.json"
    // We need the Project Name (Wind Farm) for the path.
    // If projectId is UUID, we might need to fetch project name first.
    // BUT, usually `navigationData.projectName` is available in Viewer.
    
    // Let's assume projectId passed here IS the Project Name (WindFarm) 
    // because that's how the storage structure is defined in Importer.
    // "wind_farm" variable in importer is used as root folder.
    
    // Safety check: Clean up names
    const cleanProject = projectId.trim();
    const cleanTurbine = turbineName.trim();
    const cleanBlade = `Blade ${bladeLetter.replace('Blade', '').trim().toUpperCase()}`; // Ensure "Blade A" format

    const path = `${cleanProject}/${cleanTurbine}/${cleanBlade}/manifest.json`;
    console.log(`[BladeManifestService] Fetching manifest: ${path}`);

    try {
      const { data, error } = await supabase.storage
        .from("images")
        .download(path);

      if (error) {
        console.warn(`[BladeManifestService] Manifest not found or error:`, error.message);
        return null;
      }

      if (data) {
        const text = await data.text();
        const json = JSON.parse(text);
        console.log(`[BladeManifestService] Manifest loaded for ${cleanBlade}`, json);
        return json;
      }
    } catch (err) {
      console.error(`[BladeManifestService] Error parsing manifest:`, err);
    }
    return null;
  },

  /**
   * Extract calibration data from manifest for Viewer.
   * @param {Object} manifest 
   */
  getCalibration(manifest) {
    if (!manifest) return null;

    const { bladeInfo, calibration, images } = manifest;
    
    // Default GSD from calibration or average of images
    let gsd = 0.0005; // 0.5mm/px default
    if (calibration?.globalScale) gsd = calibration.globalScale;
    else if (images && images.length > 0) {
        // Average GSD of first few images
        const sum = images.slice(0, 5).reduce((acc, img) => acc + (img.computed?.gsd || 0.5), 0);
        gsd = sum / Math.min(images.length, 5);
        // Normalize: Desktop App saves GSD in mm/px directly (e.g. 0.5)
        // Viewer expects GSD in meters? No, Viewer uses pixelScale (mm/px) usually?
        // Let's check Viewer: "gsdMeters = activePixelScale / 1000;" -> So pixelScale is mm/px.
    }

    return {
      bladeLength: bladeInfo?.length || 50000, // mm
      sequenceDirection: bladeInfo?.sequenceDirection || "Unknown",
      visualOrder: bladeInfo?.visualOrder || "TipToRoot",
      pixelScale: gsd, // mm/px
      // Root/Tip coords if needed for rotation
      rootCoords: calibration?.rootCoordinates,
      tipCoords: calibration?.tipCoordinates
    };
  }
};
